head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf30500";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — Item1, Item2, Item3, Item4, Item5, ItemA, Item6, ItemC, ItemD, Item7, Item8

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30500.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "img_19", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/main_top_3.gif"; } },
        { childId: "img_24", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/gap00.gif"; } },
        { childId: "img_45", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/dot_blue.gif"; } },
        { childId: "img_46", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/brief_column_title.gif"; } },
        { childId: "img_47", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/gap00.gif"; } },
