        { childId: "a_59", attr: "toolTip", fn: function () { return String(dma_ItemB.get("title")); } },
        { childId: "img_60", attr: "src", fn: function () { return String(String((dma_pageContext.get("releaseDomain") ?? ""))) + "/DisclosureBrief.do?method=viewBriefAttach&contnId=" + String(dma_ItemB.get("contnId")) + "&attachSeq=" + String(dma_ItemB.get("attachSeq")); } },
