        { childId: "img_102", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/dot_blue.gif"; } },
        { childId: "img_103", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/brief_example_title.gif"; } },
        { childId: "img_104", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/gap00.gif"; } },
        { childId: "img_118", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/dot_blue.gif"; } },
