        { childId: "img_189", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/brief_discls_title.gif"; } },
        { childId: "img_190", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/gap00.gif"; } },
        { childId: "img_205", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/dot_blue.gif"; } },
        { childId: "img_206", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/brief_word_title.gif"; } },
        { childId: "img_207", attr: "src", fn: function () { return String(String((dma_pageContext.get("commonImgPath") ?? ""))) + "/gap00.gif"; } },
