((dma_pageContext.get("Item7") ?? ""))).length === 0)); } }, { id: "tr_203", fn: function(){ return (!(String(((dma_pageContext.get("Item7") ?? "")) == null ? '' : ((dma_pageContext.get("Item7") ?? ""))).length === 0)); } }, { id: "tr_209", fn: function(){ return (!(String(((dma_pageContext.get("Item7") ?? "")) == null ? '' : ((dma_pageContext.get("Item7") ?? ""))).length === 0)); } }, { id: "tr_211", fn: function(){ return (!(String(((dma_pageContext.get("Item7") ?? "")) == null ? '' : ((dma_pageContext.get("Item7") ?? ""))).length === 0)); } }, { id: "tr_217", fn: function(){ return (!(String(((dma_pageContext.get("Item7") ?? "")) == null ? '' : ((dma_pageContext.get("Item7") ?? ""))).length === 0)); } }, { id: "if_Item8", fn: function(){ return (!(String(((dma_pageContext.get("Item8") ?? "")) == null ? '' : ((dma_pageContext.get("Item8") ?? ""))).length === 0)); } }, { id: "tr_220", fn: function(){ return (!(String(((dma_pageContext.get("Item8") ?? "")) == null ? '' : ((dma_pageContext.get("Item8") ?? ""))).length === 0)); } }, { id: "tr_226", fn: function(){ return (!(String(((dma_pageContext.get("Item8") ?? "")) == null ? '' : ((dma_pageContext.get("Item8") ?? ""))).length === 0)); } }, { id: "tr_228", fn: function(){ return (!(String(((dma_pageContext.get("Item8") ?? "")) == null ? '' : ((dma_pageContext.get("Item8") ?? ""))).length === 0)); } }, { id: "tr_234", fn: function(){ return (!(String(((dma_pageContext.get("Item8") ?? "")) == null ? '' : ((dma_pageContext.get("Item8") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_76", entity: "dlt_Item2", countIds: [], cells: [{ childId: "__rc3", fn: function (v, i) { return " " + String(String(v("evntnewsSchdl")).substring(0, 4)) + "/" + String(String(v("evntnewsSchdl")).substring(4, 6)); } }, { childId: "a_79", fn: function (v, i) { return String(v("title")); } }] },
        { genId: "c_foreach_93", entity: "dlt_Item3", countIds: [], cells: [{ childId: "a_95", fn: function (v, i) { return String(v("title")); } }] },
        { genId: "c_foreach_109", entity: "dlt_Item4", countIds: [], cells: [{ childId: "a_111", fn: function (v, i) { return String(v("title")); } }] },
        { genId: "c_foreach_127", entity: "dlt_Item5", countIds: [], cells: [{ childId: "a_129", fn: function (v, i) { return String(v("title")); } }] },
        { genId: "c_foreach_161", entity: "dlt_Item6", countIds: [], cells: [{ childId: "a_164", fn: function (v, i) { return String(v("title")); } }] },
        { genId: "c_foreach_179", entity: "dlt_ItemC", countIds: [], cells: [{ childId: "a_181", fn: function (v, i) { return String(v("title")); } }] },
        { genId: "c_foreach_196", entity: "dlt_ItemD", countIds: [], cells: [{ childId: "a_198", fn: function (v, i) { return String(v("title")); } }] },
        { genId: "c_foreach_213", entity: "dlt_Item7", countIds: [], cells: [{ childId: "a_215", fn: function (v, i) { return String(v("title")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "Quarterly NO. " + String(dma_ItemMaster.get("no")); } },
        { childId: "__rb1", fn: function () { return String(String(dma_ItemMaster.get("isuSchdlDd")).substring(0, 4)) + "." + String(String(dma_ItemMaster.get("isuSchdlDd")).substring(4, 6)) + "." + String(String(dma_ItemMaster.get("isuSchdlDd")).substring(6, 8)) + "(" + String(dma_ItemMaster.get("myday")) + ")"; } },
        { childId: "a_63", fn: function () { return String(String(dma_Item1.get("contnMaindocContn")).substring(0, 150)) + "..."; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldstf30500: 진입 키 disclosurebrief#viewbriefattach 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };
